), facet_names(name,label,ordinal)as(values('jurisdiction'::text,'Jurisdiction'::text,1),('kind'::text,'Evidence kind'::text,2)),
 expected_options as (
 select n.name,p.data->'publicProjection'->>n.name value,count(*)n from private_expected p cross join facet_names n group by n.name,p.data->'publicProjection'->>n.name
), actual_options as (
 select n.name,p.filters->>n.name value,count(*)n from actual p cross join facet_names n group by n.name,p.filters->>n.name
), option_checks as (
 select count(*)filter(where e.name is null or a.name is null or e.n is distinct from a.n or e.value is null or a.value is null) mismatches
 from expected_options e full join actual_options a using(name,value)
), expected_facets as (
 select jsonb_agg(jsonb_build_object('name',n.name,'type','select','label',n.label,'options',o.options)order by n.ordinal)filters
 from facet_names n join lateral(select jsonb_agg(jsonb_build_object('value',value,'label',replace(value,'_',' '),'count',v.n)order by value collate "C")options from expected_options v where v.name=n.name)o on true
), guard as (
 select (s.expected_records=25 and s.source_mismatches=0 and s.expected_fulltexts=20 and r.unexpected=0 and r.missing=0 and r.mismatched=0 and o.mismatches=0
 and (select count(*)from actual)=25 and (select count(distinct ordinal)from actual)=25
 and (select min(ordinal)from actual)=1 and (select max(ordinal)from actual)=25
 and exists(select 1 from public.corpus_datasets d where d.id='mass_tort_authority_evidence' and d.ready and d.expected_records=25 and d.imported_records=25
 and d.metadata->>'schema_version'='mass-tort-authority-evidence/1' and d.metadata->>'public_fullfield_sha256'=(select fullfield_sha256 from row_signature)))ok
 from source_checks s cross join row_checks r cross join option_checks o
)
, actual_metadata as (
 select d.id,d.ready,d.expected_records,d.imported_records,d.metadata->'listing'->'filters'filters from public.corpus_datasets d where d.id='mass_tort_authority_evidence'
), definition_checks as (
 select count(*) definitions,count(*)filter(where f->>'name'not in('jurisdiction','kind')or f->>'type'is distinct from 'select'or f?'key')invalid_definitions,
 count(distinct f->>'name')unique_names,
 (select count(*)from actual_metadata where filters is distinct from (select filters from expected_facets))metadata_mismatches
 from actual_metadata d cross join lateral jsonb_array_elements(d.filters)j(f)
)
select jsonb_build_object('verified',(select ok from guard)and(select definitions=2 and invalid_definitions=0 and unique_names=2 and metadata_mismatches=0 from definition_checks),
 'source_checks',(select to_jsonb(s)from source_checks s),'public_row_checks',(select to_jsonb(r)from row_checks r),'facet_option_mismatches',(select mismatches from option_checks),'filter_definition_checks',(select to_jsonb(c)from definition_checks c),
 'expected_filters',(select filters from expected_facets),'actual_metadata',(select to_jsonb(d)from actual_metadata d),'public_rowset_sha256',(select fullfield_sha256 from row_signature),'scope','Independent name/type/options/counts and unchanged 12-field rowset verification')receipt;
